const items = $input.all();

// Process Reddit data
const redditData = $('Fetch Reddit Tech').first().json;
const redditPosts = ((redditData.data || {}).children || []).map(p => ({
  source: 'reddit',
  title: p.data ? p.data.title : '',
  score: p.data ? p.data.score : 0,
  comments: p.data ? p.data.num_comments : 0,
  subreddit: p.data ? p.data.subreddit : '',
  created: p.data ? new Date(p.data.created_utc * 1000).toISOString() : ''
}));

// HN IDs (we'll work with what we have)
const hnIds = $('Fetch HN Top IDs').first().json || [];

// Aggregate mentions by keyword
const allTitles = redditPosts.map(p => p.title).join(' ');
const words = allTitles.toLowerCase().split(/\W+/).filter(w => w.length > 4);
const stopWords = new Set(['about', 'after', 'being', 'could', 'would', 'should', 'their', 'there', 'these', 'those', 'which', 'where', 'while', 'other', 'every', 'under', 'still', 'first']);
const wordFreq = {};
for (const w of words) {
  if (!stopWords.has(w)) wordFreq[w] = (wordFreq[w] || 0) + 1;
}

const trendingKeywords = Object.entries(wordFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 20)
  .map(([word, count]) => ({ word, count }));

const topPosts = redditPosts.sort((a, b) => b.score - a.score).slice(0, 10);

return [{
  json: {
    date: new Date().toISOString(),
    totalPostsAnalyzed: redditPosts.length,
    trendingKeywords,
    topPosts,
    hnStoriesAvailable: Array.isArray(hnIds) ? hnIds.length : 0
  }
}];
